PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE families (   id TEXT PRIMARY KEY,   name TEXT NOT NULL,   revision INTEGER NOT NULL DEFAULT 0,   created_at TEXT NOT NULL );
CREATE TABLE devices (   id TEXT PRIMARY KEY,   family_id TEXT NOT NULL,   token_hash TEXT NOT NULL UNIQUE,   name TEXT,   created_at TEXT NOT NULL,   last_seen_at TEXT NOT NULL,   revoked_at TEXT,   FOREIGN KEY (family_id) REFERENCES families(id) );
CREATE TABLE invite_codes (   code_hash TEXT PRIMARY KEY,   family_id TEXT NOT NULL,   created_by_device_id TEXT NOT NULL,   created_at TEXT NOT NULL,   expires_at TEXT NOT NULL,   used_at TEXT,   FOREIGN KEY (family_id) REFERENCES families(id),   FOREIGN KEY (created_by_device_id) REFERENCES devices(id) );
CREATE TABLE children (   id TEXT PRIMARY KEY,   family_id TEXT NOT NULL,   name TEXT NOT NULL DEFAULT '',   birth_date TEXT,   created_at TEXT NOT NULL,   updated_at TEXT NOT NULL,   deleted_at TEXT,   revision INTEGER NOT NULL,   FOREIGN KEY (family_id) REFERENCES families(id),   UNIQUE (family_id, id),   CHECK (birth_date IS NULL OR birth_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]') );
CREATE TABLE sleep_sessions (   id TEXT PRIMARY KEY,   family_id TEXT NOT NULL,   child_id TEXT NOT NULL,   start_time TEXT NOT NULL,   end_time TEXT,   note TEXT NOT NULL DEFAULT '',   day_night_override TEXT CHECK (day_night_override IS NULL OR day_night_override IN ('day', 'night')),   created_at TEXT NOT NULL,   updated_at TEXT NOT NULL,   deleted_at TEXT,   revision INTEGER NOT NULL,   FOREIGN KEY (family_id) REFERENCES families(id),   FOREIGN KEY (family_id, child_id) REFERENCES children(family_id, id) );
CREATE TABLE operations (   id TEXT PRIMARY KEY,   family_id TEXT NOT NULL,   device_id TEXT NOT NULL,   operation_type TEXT NOT NULL,   created_at TEXT NOT NULL,   FOREIGN KEY (family_id) REFERENCES families(id),   FOREIGN KEY (device_id) REFERENCES devices(id) );
CREATE TABLE accounts (
  id TEXT PRIMARY KEY NOT NULL,
  email TEXT,
  display_name TEXT,
  avatar_url TEXT,
  locale TEXT,
  status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (status IN ('ACTIVE', 'DELETION_PENDING', 'DELETED')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  last_login_at INTEGER NOT NULL,
  deleted_at INTEGER,
  CHECK ((status = 'DELETED') = (deleted_at IS NOT NULL))
);
CREATE TABLE account_identities (
  id TEXT PRIMARY KEY NOT NULL,
  account_id TEXT NOT NULL,
  provider TEXT NOT NULL CHECK (provider = 'GOOGLE'),
  issuer TEXT NOT NULL,
  subject TEXT NOT NULL CHECK (length(subject) > 0),
  email_at_login TEXT,
  email_verified INTEGER NOT NULL CHECK (email_verified IN (0, 1)),
  created_at INTEGER NOT NULL,
  last_verified_at INTEGER NOT NULL,
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,
  UNIQUE (provider, issuer, subject)
);
CREATE TABLE account_devices (
  id TEXT PRIMARY KEY NOT NULL,
  account_id TEXT NOT NULL,
  installation_hash TEXT NOT NULL UNIQUE,
  credential_hash TEXT NOT NULL UNIQUE,
  name TEXT,
  platform TEXT CHECK (platform IN ('WEB', 'IOS', 'ANDROID', 'OTHER')),
  created_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  revoked_at INTEGER,
  revoke_reason TEXT CHECK (revoke_reason IS NULL OR revoke_reason IN
    ('USER_REPLACED', 'USER_REVOKED', 'SECURITY', 'ACCOUNT_DELETED')),
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,
  UNIQUE (account_id, id),
  CHECK ((revoked_at IS NULL) = (revoke_reason IS NULL))
);
CREATE TABLE account_sessions (
  id TEXT PRIMARY KEY NOT NULL,
  account_id TEXT NOT NULL,
  device_id TEXT NOT NULL,
  refresh_hash TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  last_used_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  revoked_at INTEGER,
  rotation_counter INTEGER NOT NULL DEFAULT 0 CHECK (rotation_counter >= 0),
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,
  FOREIGN KEY (account_id, device_id) REFERENCES account_devices(account_id, id) ON DELETE CASCADE,
  CHECK (expires_at > created_at)
);
CREATE TABLE auth_challenges (
  nonce_hash TEXT PRIMARY KEY NOT NULL,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL CHECK (expires_at > created_at)
);
CREATE TABLE used_refresh_tokens (
  token_hash TEXT PRIMARY KEY NOT NULL,
  session_id TEXT NOT NULL,
  used_at INTEGER NOT NULL,
  FOREIGN KEY (session_id) REFERENCES account_sessions(id) ON DELETE CASCADE
);
CREATE TABLE legacy_family_memberships (
  id TEXT PRIMARY KEY NOT NULL,
  family_id TEXT NOT NULL,
  account_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('ADMIN', 'MEMBER')),
  status TEXT NOT NULL DEFAULT 'ACTIVE'
    CHECK (status IN ('ACTIVE', 'LEFT', 'REMOVED')),
  joined_at INTEGER NOT NULL,
  ended_at INTEGER,
  FOREIGN KEY (family_id) REFERENCES families(id) ON DELETE CASCADE,
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,
  CHECK ((status = 'ACTIVE') = (ended_at IS NULL))
);
CREATE TABLE account_family_devices (
  account_device_id TEXT PRIMARY KEY NOT NULL,
  account_id TEXT NOT NULL,
  family_id TEXT NOT NULL,
  legacy_device_id TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (account_id, account_device_id)
    REFERENCES account_devices(account_id, id) ON DELETE CASCADE,
  FOREIGN KEY (family_id) REFERENCES families(id) ON DELETE CASCADE,
  FOREIGN KEY (legacy_device_id) REFERENCES devices(id) ON DELETE CASCADE
);
CREATE TABLE subscriptions (
  id TEXT PRIMARY KEY NOT NULL,
  account_id TEXT NOT NULL,
  provider TEXT NOT NULL CHECK (provider IN ('APPLE', 'GOOGLE_PLAY', 'STRIPE', 'MANUAL')),
  provider_subscription_id TEXT NOT NULL,
  product TEXT NOT NULL CHECK (product IN ('FAMILY', 'FAMILY_PLUS')),
  status TEXT NOT NULL CHECK (status IN
    ('TRIALING', 'ACTIVE', 'GRACE_PERIOD', 'PAST_DUE', 'CANCELED', 'EXPIRED', 'REVOKED')),
  auto_renews INTEGER NOT NULL CHECK (auto_renews IN (0, 1)),
  trial_ends_at INTEGER,
  current_period_ends_at INTEGER NOT NULL,
  access_until INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  canceled_at INTEGER,
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE RESTRICT,
  UNIQUE (provider, provider_subscription_id),
  CHECK (access_until >= created_at),
  CHECK (trial_ends_at IS NULL OR trial_ends_at > created_at)
);
CREATE TABLE subscription_events (
  id TEXT PRIMARY KEY NOT NULL,
  provider TEXT NOT NULL CHECK (provider IN ('APPLE', 'GOOGLE_PLAY', 'STRIPE', 'MANUAL')),
  provider_event_id TEXT NOT NULL,
  subscription_id TEXT,
  event_type TEXT NOT NULL,
  occurred_at INTEGER NOT NULL,
  received_at INTEGER NOT NULL,
  payload_hash TEXT NOT NULL,
  processed_at INTEGER,
  processing_error TEXT,
  FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL,
  UNIQUE (provider, provider_event_id)
);
CREATE TABLE account_entitlements (
  id TEXT PRIMARY KEY NOT NULL,
  account_id TEXT NOT NULL,
  feature_key TEXT NOT NULL CHECK (feature_key IN
    ('FAMILY_SYNC', 'PDF_EXPORT', 'FAMILY_PLUS_INSIGHTS')),
  source_type TEXT NOT NULL CHECK (source_type IN ('SUBSCRIPTION', 'PROMO', 'ADMIN')),
  source_id TEXT NOT NULL,
  valid_from INTEGER NOT NULL,
  valid_until INTEGER NOT NULL,
  revoked_at INTEGER,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,
  CHECK (valid_until > valid_from),
  UNIQUE (account_id, feature_key, source_type, source_id)
);
CREATE INDEX idx_devices_family ON devices(family_id);
CREATE INDEX idx_invites_family ON invite_codes(family_id);
CREATE INDEX idx_invites_expires ON invite_codes(expires_at);
CREATE INDEX idx_children_family_revision ON children(family_id, revision);
CREATE INDEX idx_children_family_active ON children(family_id, deleted_at);
CREATE INDEX idx_sessions_family_revision ON sleep_sessions(family_id, revision);
CREATE INDEX idx_sessions_family_child_start ON sleep_sessions(family_id, child_id, start_time);
CREATE UNIQUE INDEX idx_one_active_sleep_per_child ON sleep_sessions(family_id, child_id) WHERE end_time IS NULL AND deleted_at IS NULL;
CREATE INDEX idx_operations_family ON operations(family_id);
CREATE INDEX idx_operations_created ON operations(created_at);
CREATE UNIQUE INDEX idx_one_google_identity_per_account
ON account_identities(account_id) WHERE provider = 'GOOGLE';
CREATE INDEX idx_account_devices_active
ON account_devices(account_id, last_seen_at DESC) WHERE revoked_at IS NULL;
CREATE INDEX idx_account_sessions_device_active
ON account_sessions(device_id, expires_at) WHERE revoked_at IS NULL;
CREATE INDEX idx_auth_challenges_expiry ON auth_challenges(expires_at);
CREATE INDEX idx_used_refresh_session ON used_refresh_tokens(session_id);
CREATE UNIQUE INDEX idx_one_active_legacy_family_per_account
ON legacy_family_memberships(account_id) WHERE status = 'ACTIVE';
CREATE UNIQUE INDEX idx_one_active_legacy_membership_per_family_account
ON legacy_family_memberships(family_id, account_id) WHERE status = 'ACTIVE';
CREATE UNIQUE INDEX idx_one_active_legacy_family_admin
ON legacy_family_memberships(family_id) WHERE status = 'ACTIVE' AND role = 'ADMIN';
CREATE INDEX idx_account_family_devices_family
ON account_family_devices(family_id, account_id);
CREATE INDEX idx_subscriptions_account_access
ON subscriptions(account_id, access_until DESC);
CREATE INDEX idx_account_entitlements_active
ON account_entitlements(account_id, feature_key, valid_until)
WHERE revoked_at IS NULL;
CREATE TRIGGER account_devices_max_two_insert
BEFORE INSERT ON account_devices
WHEN NEW.revoked_at IS NULL AND
  (SELECT COUNT(*) FROM account_devices
   WHERE account_id = NEW.account_id AND revoked_at IS NULL) >= 2
BEGIN
  SELECT RAISE(ABORT, 'ACCOUNT_DEVICE_LIMIT');
END;
CREATE TRIGGER account_devices_max_two_update
BEFORE UPDATE OF revoked_at, account_id ON account_devices
WHEN NEW.revoked_at IS NULL AND
  (SELECT COUNT(*) FROM account_devices
   WHERE account_id = NEW.account_id AND revoked_at IS NULL AND id != OLD.id) >= 2
BEGIN
  SELECT RAISE(ABORT, 'ACCOUNT_DEVICE_LIMIT');
END;
CREATE TRIGGER account_family_devices_require_membership
BEFORE INSERT ON account_family_devices
WHEN NOT EXISTS (
  SELECT 1 FROM legacy_family_memberships m
  WHERE m.family_id = NEW.family_id
    AND m.account_id = NEW.account_id
    AND m.status = 'ACTIVE'
)
BEGIN
  SELECT RAISE(ABORT, 'ACTIVE_FAMILY_MEMBERSHIP_REQUIRED');
END;
CREATE TRIGGER account_family_devices_match_legacy_family
BEFORE INSERT ON account_family_devices
WHEN NOT EXISTS (
  SELECT 1 FROM devices d
  WHERE d.id = NEW.legacy_device_id AND d.family_id = NEW.family_id
)
BEGIN
  SELECT RAISE(ABORT, 'LEGACY_DEVICE_FAMILY_MISMATCH');
END;
